/**
 * Flow Diagnostics Plugin
 *
 * This plugin validates that flow-related constructs (wfa.action, wfa.subflow, wfa.flowLogic.*)
 * are only used inside Flow or Subflow bodies, not at the top level or outside flow context.
 */
import { Plugin } from '@servicenow/sdk-build-core';
/**
 * Flow Placement Diagnostics Plugin
 *
 * Validates placement of:
 * - wfa.action
 * - wfa.subflow
 * - wfa.trigger (must be within Flow)
 * - wfa.flowLogic.if
 * - wfa.flowLogic.elseIf
 * - wfa.flowLogic.else
 * - wfa.flowLogic.forEach
 * - wfa.flowLogic.waitForADuration
 * - wfa.flowLogic.goBackTo
 * - wfa.flowLogic.tryCatch
 * - wfa.flowLogic.doInParallel
 * - FlowObject (must be within Flow/Subflow/ActionDefinition/SubflowDefinition/TriggerDefinition)
 * - FlowArray (must be within Flow/Subflow/ActionDefinition/SubflowDefinition/TriggerDefinition)
 */
export declare const FlowDiagnosticsPlugin: Plugin;
